import type { Metadata } from "next";

import { QrLanding } from "@/components/QrLanding";
import { site } from "@/data/content/site";
import { getPlacementEntry, listActivePlacements, resolvePlacement } from "@/lib/placements";

/**
 * QR landing route (FR-1).
 *
 * `generateStaticParams` prerenders the known placements; `dynamicParams`
 * stays at its default of `true` so an unrecognised code renders on demand
 * with HTTP 200 and `placement: "unknown"` — it must NEVER 404 (FR-4, C-14).
 * That requirement is also why this app runs as a server (`next start`) rather
 * than a static `output: "export"` build: static export does not support
 * `dynamicParams: true`.
 */
export function generateStaticParams() {
  return listActivePlacements().map((entry) => ({ placement: entry.code }));
}

interface PageProps {
  params: Promise<{ placement: string }>;
}

async function resolveFromParams(params: Promise<{ placement: string }>) {
  const raw = (await params).placement;
  try {
    return resolvePlacement(decodeURIComponent(raw));
  } catch {
    return resolvePlacement(raw);
  }
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { placement, valid } = await resolveFromParams(params);
  const label = valid ? getPlacementEntry(placement)?.label : undefined;
  return {
    title: label ? `${label} — ${site.qrTitleSuffix}` : site.qrTitle,
    description: site.qrDescription,
  };
}

export default async function QrLandingPage({ params }: PageProps) {
  const { placement } = await resolveFromParams(params);
  return <QrLanding placement={placement} />;
}
