import { DiscountBanner } from "@/components/DiscountBanner";
import { Handoff } from "@/components/Handoff";
import { Hero } from "@/components/Hero";
import { SiteFooter } from "@/components/SiteFooter";
import { SiteHeader } from "@/components/SiteHeader";
import { config } from "@/config";
import { landing } from "@/data/content/landing";
import { buildWhatsAppUrl } from "@/lib/whatsapp";

/**
 * Server-rendered `href` for a QR landing.
 *
 * C-8: the discount CODE is deliberately `null` here — it only exists in the
 * client bundle, so this response stays identical for every visitor. `Handoff`
 * upgrades the anchor after hydration once the cookie is read.
 */
export function qrBaseHref(placement: string): string {
  return buildWhatsAppUrl({
    placement,
    discountCode: null,
    route: "qr",
    config: {
      whatsappNumber: config.NEXT_PUBLIC_WHATSAPP_NUMBER,
      discountPercent: config.NEXT_PUBLIC_DISCOUNT_PERCENT,
    },
  });
}

/**
 * Body of every QR landing (FR-1). Shared by `/l/[placement]` and the
 * degenerate `/l` case so the conversion route can never 404 (FR-4, product
 * principle 3 — "no dead ends").
 */
export function QrLanding({ placement }: { placement: string }) {
  return (
    <>
      <div className="mx-auto w-full max-w-3xl px-4 pt-4 sm:px-6">
        <DiscountBanner />
      </div>
      <SiteHeader />
      <Hero>
        <Handoff
          placement={placement}
          baseHref={qrBaseHref(placement)}
          ctaLocation="landing"
          label={landing.ctaLabel}
          className="inline-flex w-full items-center justify-center rounded-2xl bg-emerald-700 px-6 py-4 text-base font-semibold text-white shadow-sm outline-offset-2 hover:bg-emerald-800 focus-visible:outline focus-visible:outline-2 focus-visible:outline-emerald-600 sm:w-auto"
        />
      </Hero>
      <SiteFooter />
    </>
  );
}
